//----------------------------------------------------------------------
// Implementation-defined
//
// Ordering for containers keyed by register model objects (blocks,
// maps, registers, memories, ...). Objects are ordered by their
// instance id, i.e. in creation order, so that iterating such a
// container does not depend on where the objects are allocated.
//----------------------------------------------------------------------

struct uvm_reg_creation_order
{
  template <typename T>
  bool operator()( const T* a, const T* b ) const
  {
    if (a == b || a == nullptr || b == nullptr)
      return a < b;
    return a->get_inst_id() < b->get_inst_id();
  }
};

